import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load textures
  const colorTexture = ctx.textureLoader.load(config.assets.imageUrl);
  const depthTexture = ctx.textureLoader.load(config.assets.depthMapUrl);

  colorTexture.colorSpace = THREE.SRGBColorSpace;

  // Create tessellated plane geometry (64x64 segments for parallax detail)
  // Aspect ratio 512:320 = 1.6:1
  const geometry = new THREE.PlaneGeometry(1, 0.625, 64, 64);

  // Apply vertex displacement from depth map
  try {
    const depthImage = depthTexture.image;
    const depthWidth = depthImage.width;
    const depthHeight = depthImage.height;

    let depthData = null;

    // Try to read depth texture data via OffscreenCanvas
    if (typeof OffscreenCanvas !== 'undefined') {
      const canvas = new OffscreenCanvas(depthWidth, depthHeight);
      const ctx2d = canvas.getContext('2d');
      ctx2d.drawImage(depthImage, 0, 0);
      const imageData = ctx2d.getImageData(0, 0, depthWidth, depthHeight);
      depthData = imageData.data;
    }

    // Apply displacement if depth data is available
    if (depthData) {
      const positionAttribute = geometry.getAttribute('position');
      const uvAttribute = geometry.getAttribute('uv');
      const displacementScale = 0.05;

      for (let i = 0; i < positionAttribute.count; i++) {
        const u = uvAttribute.getX(i);
        const v = uvAttribute.getY(i);

        const pixelX = Math.floor(u * (depthWidth - 1));
        const pixelY = Math.floor((1 - v) * (depthHeight - 1));
        const pixelIndex = (pixelY * depthWidth + pixelX) * 4;

        const r = depthData[pixelIndex] || 0;
        const g = depthData[pixelIndex + 1] || 0;
        const b = depthData[pixelIndex + 2] || 0;
        const depthValue = (r + g + b) / 765;

        const z = positionAttribute.getZ(i);
        const displacement = (depthValue - 0.5) * displacementScale * 2;
        positionAttribute.setZ(i, z + displacement);
      }

      positionAttribute.needsUpdate = true;
      geometry.computeVertexNormals();
    }
  } catch (err) {
    // Silently continue without displacement if depth reading fails
  }

  // Create material with color texture
  const material = new THREE.MeshStandardMaterial({
    color: new THREE.Color('#ffffff'),
    metalness: 0.1,
    roughness: 0.8,
    map: colorTexture,
  });

  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // State management for interactions
  let hoverTimeline = null;
  let pressTimeline = null;

  // Interaction handlers
  const handlers = {
    onPointerEnter: () => {
      if (hoverTimeline) hoverTimeline.kill();
      // Rise-in: 0.15 units, power3.out, 0.7s
      hoverTimeline = gsap.to(mesh.position, {
        y: 0.15,
        duration: 0.7,
        ease: 'power3.out',
      });
    },
    onPointerLeave: () => {
      if (hoverTimeline) hoverTimeline.kill();
      hoverTimeline = gsap.to(mesh.position, {
        y: 0,
        duration: 0.7,
        ease: 'power3.out',
      });
    },
    onPointerDown: () => {
      // Press-down: scale to 0.97, back.out, 0.12s
      if (pressTimeline) pressTimeline.kill();
      pressTimeline = gsap.to(mesh.scale, {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'back.out',
      });
    },
    onPointerUp: () => {
      // Release press
      if (pressTimeline) pressTimeline.kill();
      pressTimeline = gsap.to(mesh.scale, {
        x: 1,
        y: 1,
        duration: 0.12,
        ease: 'back.out',
      });
    },
  };

  // Set scene placement
  group.position.set(-1.25, 1.6, 0);
  group.scale.set(1, 1, 1);

  // Setup userData with handlers and cleanup
  group.userData = {
    handlers,
    cleanup: () => {
      if (hoverTimeline) hoverTimeline.kill();
      if (pressTimeline) pressTimeline.kill();
      geometry.dispose();
      material.dispose();
      colorTexture.dispose();
      depthTexture.dispose();
    },
  };

  return group;
}
